<style>
.sa-page{display:grid;gap:16px}.sa-page .page-title{font-size:28px;line-height:1.1}.sa-page .page-subtitle{margin-top:4px}.sa-message{display:none}.sa-message.show{display:block}.sa-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}.sa-stat{border:0;border-radius:14px;min-height:100px;padding:17px 18px;color:#fff;display:flex;align-items:center;gap:13px;position:relative;overflow:hidden}.sa-stat::after{content:"";position:absolute;width:100px;height:100px;border-radius:50%;right:-34px;top:-38px;background:rgba(255,255,255,.08)}.sa-stat.purple{background:linear-gradient(135deg,#7158e8,#4f46d9)}.sa-stat.green{background:linear-gradient(135deg,#45c783,#1ea568)}.sa-stat.red{background:linear-gradient(135deg,#ff647d,#dc3545)}.sa-stat.orange{background:linear-gradient(135deg,#ffb327,#ff8a17)}.sa-stat.blue{background:linear-gradient(135deg,#4696ef,#2469d5)}.sa-stat span{width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.16);display:grid;place-items:center}.sa-stat svg{width:22px;height:22px}.sa-stat strong{display:block;font-size:23px;line-height:1}.sa-stat small{display:block;font-size:10px;font-weight:800;margin-bottom:6px}.sa-card{border-radius:14px;overflow:hidden}.sa-card-head{padding:14px 16px;border-bottom:1px solid var(--border-soft,#e7ebf3);display:flex;align-items:center;justify-content:space-between;gap:10px}.sa-filter{padding:14px 16px;display:grid;grid-template-columns:repeat(3,minmax(160px,.75fr)) minmax(220px,1.2fr) auto;gap:10px}.sa-actions{padding:0 16px 14px;display:flex;gap:8px;flex-wrap:wrap}.sa-table-wrap{overflow:auto}.sa-table{min-width:1260px}.sa-table th{font-size:10px;white-space:nowrap}.sa-table td{font-size:11px;vertical-align:middle}.sa-empty{padding:42px 18px!important;text-align:center!important;color:var(--text-muted,#64748b)}.sa-staff{display:flex;align-items:center;gap:9px}.sa-avatar{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;color:#fff;font-weight:800;background:linear-gradient(135deg,#6d4ce7,#345fe0)}.sa-badge{display:inline-flex;padding:5px 9px;border-radius:999px;font-size:9px;font-weight:800;text-transform:capitalize}.sa-badge.present{color:#16834f;background:#e8f8ef}.sa-badge.absent{color:#dc2626;background:#fff0f1}.sa-badge.late,.sa-badge.half_day{color:#9a6700;background:#fff7d6}.sa-badge.not_marked{color:#475569;background:#eef2f7}.sa-status-select{min-width:110px}.sa-settings-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.sa-settings-grid .full{grid-column:1/-1}.sa-footer{padding:14px 16px;border-top:1px solid var(--border-soft,#e7ebf3);display:flex;justify-content:space-between;gap:10px;align-items:center}.sa-punch{display:flex;gap:5px;flex-wrap:wrap}.sa-report-filter{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr)) auto;gap:10px;padding:16px}.sa-modal-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.sa-modal-grid .full{grid-column:1/-1}@media(max-width:1100px){.sa-filter,.sa-report-filter{grid-template-columns:repeat(2,1fr)}.sa-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.sa-stats,.sa-filter,.sa-report-filter,.sa-settings-grid,.sa-modal-grid{grid-template-columns:1fr}.sa-settings-grid .full,.sa-modal-grid .full{grid-column:auto}.sa-card-head,.sa-footer{align-items:flex-start;flex-direction:column}}
</style>
<div class="sa-page">
<div class="page-heading"><div><h1 class="page-title">Staff Attendance</h1><p class="page-subtitle">Mark daily attendance, punch timings and view simple reports.</p></div><div class="page-actions"><button id="settingsBtn" class="btn-ui" type="button"><i data-lucide="settings"></i> Settings</button><button id="refreshBtn" class="btn-ui" type="button"><i data-lucide="refresh-cw"></i> Refresh</button></div></div>
<div id="saMessage" class="alert sa-message"></div>
<section class="sa-stats"><article class="sa-stat purple"><span><i data-lucide="users"></i></span><div><small>Total Staff</small><strong id="statTotal">0</strong></div></article><article class="sa-stat green"><span><i data-lucide="user-check"></i></span><div><small>Present</small><strong id="statPresent">0</strong></div></article><article class="sa-stat red"><span><i data-lucide="user-x"></i></span><div><small>Absent</small><strong id="statAbsent">0</strong></div></article><article class="sa-stat orange"><span><i data-lucide="clock-3"></i></span><div><small>Late / Half Day</small><strong id="statLate">0</strong></div></article><article class="sa-stat blue"><span><i data-lucide="circle-dashed"></i></span><div><small>Not Marked</small><strong id="statNotMarked">0</strong></div></article></section>
<section class="ui-card sa-card"><div class="sa-card-head"><strong>Daily Attendance</strong><small id="locationHint" class="text-muted">Location attendance disabled.</small></div><div class="sa-filter"><div><label class="form-label">Attendance Date</label><input id="attendanceDate" type="date" class="form-control"></div><div><label class="form-label">Staff Type</label><select id="staffType" class="form-select"><option value="all">All Staff</option><option value="teaching">Teaching</option><option value="non_teaching">Non-Teaching</option></select></div><div><label class="form-label">Attendance Status</label><select id="statusFilter" class="form-select"><option value="all">All Statuses</option><option value="present">Present</option><option value="absent">Absent</option><option value="late">Late</option><option value="half_day">Half Day</option></select></div><div><label class="form-label">Search Staff</label><input id="staffSearch" class="form-control" placeholder="Staff ID, name or mobile..."></div><div style="align-self:end"><button id="loadBtn" class="btn-ui btn-primary-ui" type="button"><i data-lucide="search"></i> Load Staff</button></div></div><div class="sa-actions"><button id="allPresentBtn" class="btn-ui" type="button"><i data-lucide="check-check"></i> Mark All Present</button><button id="allAbsentBtn" class="btn-ui" type="button"><i data-lucide="x-circle"></i> Mark All Absent</button><button id="exportBtn" class="btn-ui" type="button"><i data-lucide="sheet"></i> Export Excel</button><button id="printBtn" class="btn-ui" type="button"><i data-lucide="printer"></i> Print</button></div><div class="sa-table-wrap"><table class="data-table sa-table"><thead><tr><th>Staff ID</th><th>Staff Name</th><th>Staff Type</th><th>Department</th><th>Punch In</th><th>Punch Out</th><th>Working Hours</th><th>Attendance Status</th><th>Action</th></tr></thead><tbody id="attendanceBody"><tr><td colspan="9" class="sa-empty">Loading staff...</td></tr></tbody></table></div><div class="sa-footer"><small id="recordInfo" class="text-muted"></small><small class="text-muted">Attendance is saved immediately after confirmation.</small></div></section>
</div>
<div class="modal fade" id="editAttendanceModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form id="editAttendanceForm"><div class="modal-header"><div><h5 class="modal-title">Edit Staff Attendance</h5><small id="editStaffName" class="text-muted"></small></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input id="editStaffId" type="hidden"><div class="sa-modal-grid"><div><label class="form-label">Attendance Status</label><select id="editStatus" class="form-select" required><option value="present">Present</option><option value="absent">Absent</option><option value="late">Late</option><option value="half_day">Half Day</option></select></div><div><label class="form-label">Attendance Date</label><input id="editDate" class="form-control" readonly></div><div><label class="form-label">Punch In Time</label><input id="editPunchIn" type="time" class="form-control"></div><div><label class="form-label">Punch Out Time</label><input id="editPunchOut" type="time" class="form-control"></div><div class="full"><label class="form-label">Remarks</label><textarea id="editRemarks" class="form-control" rows="3" maxlength="255"></textarea></div></div></div><div class="modal-footer"><button type="button" class="btn-ui" data-bs-dismiss="modal">Cancel</button><button type="submit" class="btn-ui btn-primary-ui"><i data-lucide="save"></i> Save Attendance</button></div></form></div></div></div>
<div class="modal fade" id="settingsModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form id="settingsForm"><div class="modal-header"><div><h5 class="modal-title">Attendance Settings</h5><small class="text-muted">Location and office time configuration.</small></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="sa-settings-grid"><div class="full form-check form-switch"><input id="locationEnabled" class="form-check-input" type="checkbox"><label class="form-check-label" for="locationEnabled">Enable Location-Based Attendance</label></div><div><label class="form-label">School Latitude</label><input id="schoolLatitude" class="form-control" inputmode="decimal" placeholder="12.9715987"></div><div><label class="form-label">School Longitude</label><input id="schoolLongitude" class="form-control" inputmode="decimal" placeholder="77.5945627"></div><div><label class="form-label">Allowed Radius (Metres)</label><input id="allowedRadius" type="number" min="10" max="5000" class="form-control" value="100"></div><div><label class="form-label">Office Start Time</label><input id="officeStart" type="time" class="form-control"></div><div><label class="form-label">Late Arrival Time</label><input id="lateTime" type="time" class="form-control"></div><div style="align-self:end"><button id="useCurrentLocation" class="btn-ui" type="button"><i data-lucide="map-pin"></i> Use Current Location</button></div></div></div><div class="modal-footer"><button type="button" class="btn-ui" data-bs-dismiss="modal">Cancel</button><button type="submit" class="btn-ui btn-primary-ui"><i data-lucide="save"></i> Save Settings</button></div></form></div></div></div>
<script>
(function(){'use strict';
const apiUrl=new URL('../api/staff-attendance.php',window.location.href).href;let csrfToken=<?=json_encode($attendanceCsrf)?>,meta={},rows=[],searchTimer=null;const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const badge=v=>`<span class="sa-badge ${esc(v)}">${esc(String(v).replace('_',' '))}</span>`;
function today(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
async function request(action,data={},method='GET'){let response;if(method==='GET'){const u=new URL(apiUrl);u.searchParams.set('action',action);Object.entries(data).forEach(([k,v])=>{if(v!==''&&v!==null&&v!==undefined)u.searchParams.set(k,v)});response=await fetch(u,{headers:{Accept:'application/json'},credentials:'same-origin'})}else response=await fetch(apiUrl,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},credentials:'same-origin',body:JSON.stringify({action,csrf_token:csrfToken,...data})});const text=await response.text();let result;try{result=JSON.parse(text)}catch{throw new Error(`Staff Attendance API returned HTTP ${response.status}. ${text.replace(/\s+/g,' ').slice(0,200)}`)}if(!response.ok||!result.success)throw new Error(result.message||'Request failed.');if(result.data?.csrf_token)csrfToken=result.data.csrf_token;return result}
function message(text,ok=false){const b=$('saMessage');b.className='alert sa-message show '+(ok?'alert-success':'alert-danger');b.textContent=text;clearTimeout(b._t);b._t=setTimeout(()=>b.className='alert sa-message',6500)}
function filters(){return{attendance_date:$('attendanceDate').value,staff_type:$('staffType').value,attendance_status:$('statusFilter').value,search:$('staffSearch').value.trim()}}
function render(){const canEdit=!!meta.can_edit;$('attendanceBody').innerHTML=rows.map(r=>{const initials=(r.staff_name||'?').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();const punch=meta.settings?.location_enabled?`<div class="sa-punch"><button class="btn-ui btn-sm js-punch-in" data-id="${r.id}" type="button" ${r.punch_in?'disabled':''}>In</button><button class="btn-ui btn-sm js-punch-out" data-id="${r.id}" type="button" ${!r.punch_in||r.punch_out?'disabled':''}>Out</button></div>`:'';return `<tr><td><strong>${esc(r.staff_code)}</strong></td><td><div class="sa-staff"><span class="sa-avatar">${esc(initials)}</span><div><strong>${esc(r.staff_name)}</strong><small class="text-muted">${esc(r.designation_name||'-')}</small></div></div></td><td>${esc(String(r.staff_type).replace('_',' '))}</td><td>${esc(r.department_name||'-')}</td><td>${esc(r.punch_in_time||'-')}</td><td>${esc(r.punch_out_time||'-')}</td><td><strong>${esc(r.working_hours)}</strong></td><td>${badge(r.attendance_status)}</td><td><div class="sa-punch">${punch}<button class="btn-ui btn-sm js-edit" data-id="${r.id}" type="button" ${canEdit?'':'disabled'}><i data-lucide="pencil"></i> Edit</button></div></td></tr>`}).join('')||'<tr><td colspan="9" class="sa-empty">No staff found.</td></tr>';$('recordInfo').textContent=`Showing ${rows.length} staff`;document.querySelectorAll('.js-edit').forEach(b=>b.onclick=()=>openEdit(Number(b.dataset.id)));document.querySelectorAll('.js-punch-in').forEach(b=>b.onclick=()=>punch(Number(b.dataset.id),'punch_in'));document.querySelectorAll('.js-punch-out').forEach(b=>b.onclick=()=>punch(Number(b.dataset.id),'punch_out'));window.lucide?.createIcons()}
function renderStats(s={}){$('statTotal').textContent=s.total||0;$('statPresent').textContent=s.present||0;$('statAbsent').textContent=s.absent||0;$('statLate').textContent=(s.late||0)+(s.half_day||0);$('statNotMarked').textContent=s.not_marked||0}
async function load(){try{const r=await request('list',filters());rows=r.data.records||[];renderStats(r.data.stats||{});render()}catch(e){message(e.message)}}
function openEdit(id){const r=rows.find(x=>Number(x.id)===id);if(!r)return;$('editStaffId').value=id;$('editStaffName').textContent=`${r.staff_code} · ${r.staff_name}`;$('editDate').value=$('attendanceDate').value;$('editStatus').value=r.attendance_status==='not_marked'?'present':r.attendance_status;$('editPunchIn').value=r.punch_in?String(r.punch_in).slice(11,16):'';$('editPunchOut').value=r.punch_out?String(r.punch_out).slice(11,16):'';$('editRemarks').value=r.remarks||'';bootstrap.Modal.getOrCreateInstance($('editAttendanceModal')).show()}
async function bulk(status){if(!confirm(`Mark all loaded ${$('staffType').selectedOptions[0].text} as ${status}?`))return;try{const r=await request('bulk',{attendance_date:$('attendanceDate').value,staff_type:$('staffType').value,attendance_status:status},'POST');message(r.message,true);await load()}catch(e){message(e.message)}}
function getLocation(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error('GPS is not supported by this browser.'));navigator.geolocation.getCurrentPosition(p=>resolve({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}),e=>reject(new Error(e.message||'Unable to get GPS location.')),{enableHighAccuracy:true,timeout:15000,maximumAge:0})})}
async function punch(staffId,action){try{const gps=await getLocation();const r=await request(action,{staff_id:staffId,...gps},'POST');message(r.message+(r.data.distance!==null?` (${Math.round(r.data.distance)} m from school)`:'') ,true);await load()}catch(e){message(e.message)}}
function applySettings(){const s=meta.settings||{};$('locationEnabled').checked=Number(s.location_enabled)===1;$('schoolLatitude').value=s.school_latitude||'';$('schoolLongitude').value=s.school_longitude||'';$('allowedRadius').value=s.allowed_radius_meters||100;$('officeStart').value=String(s.office_start_time||'09:00').slice(0,5);$('lateTime').value=String(s.late_after_time||'09:15').slice(0,5);$('locationHint').textContent=Number(s.location_enabled)===1?`GPS enabled · ${s.allowed_radius_meters} metre school radius`:'Location attendance disabled.'}
async function init(){try{$('attendanceDate').value=today();const r=await request('meta');meta=r.data;applySettings();await load()}catch(e){message(e.message)}}
$('editAttendanceForm').onsubmit=async e=>{e.preventDefault();try{const r=await request('save',{staff_id:Number($('editStaffId').value),attendance_date:$('editDate').value,attendance_status:$('editStatus').value,punch_in_time:$('editPunchIn').value,punch_out_time:$('editPunchOut').value,remarks:$('editRemarks').value.trim()},'POST');bootstrap.Modal.getInstance($('editAttendanceModal'))?.hide();message(r.message,true);await load()}catch(x){message(x.message)}};
$('settingsForm').onsubmit=async e=>{e.preventDefault();try{const r=await request('save_settings',{location_enabled:$('locationEnabled').checked?1:0,school_latitude:$('schoolLatitude').value.trim(),school_longitude:$('schoolLongitude').value.trim(),allowed_radius_meters:Number($('allowedRadius').value),office_start_time:$('officeStart').value,late_after_time:$('lateTime').value},'POST');bootstrap.Modal.getInstance($('settingsModal'))?.hide();message(r.message,true);const m=await request('meta');meta=m.data;applySettings();render()}catch(x){message(x.message)}};
$('useCurrentLocation').onclick=async()=>{try{const p=await getLocation();$('schoolLatitude').value=p.latitude.toFixed(7);$('schoolLongitude').value=p.longitude.toFixed(7);message('Current GPS coordinates loaded.',true)}catch(e){message(e.message)}};$('settingsBtn').onclick=()=>{applySettings();bootstrap.Modal.getOrCreateInstance($('settingsModal')).show()};$('loadBtn').onclick=load;$('refreshBtn').onclick=load;$('allPresentBtn').onclick=()=>bulk('present');$('allAbsentBtn').onclick=()=>bulk('absent');$('attendanceDate').onchange=load;$('staffType').onchange=load;$('statusFilter').onchange=load;$('staffSearch').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(load,300)};$('exportBtn').onclick=()=>{const q=new URLSearchParams({action:'export_excel',...filters()});window.location.href=apiUrl+'?'+q};$('printBtn').onclick=()=>window.print();init();window.lucide?.createIcons();
})();
</script>
<?php require dirname(__DIR__).'/includes/layout-end.php'; ?>
